import math

def test_fan_in_256():
    assert abs(solution.he_std(256) - math.sqrt(2 / 256)) < 1e-12

def test_fan_in_16():
    assert abs(solution.he_std(16) - 0.35355339059327373) < 1e-9

def test_fan_in_2():
    assert abs(solution.he_std(2) - 1.0) < 1e-12

def test_zero_raises():
    try:
        solution.he_std(0)
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_negative_raises():
    try:
        solution.he_std(-4)
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_large():
    assert abs(solution.he_std(1024) - math.sqrt(2 / 1024)) < 1e-12

def test_returns_float():
    assert isinstance(solution.he_std(8), float)
